// #db7e39 — общие шаги окон подтверждения (role=dialog, кнопки «חזרה» / действие, фокус на «חזרה»).
// Тексты и роли проверены по живому staging 15.11.2026 (ADMIN2, компания B).
import { Locator, Page, expect } from '@playwright/test';

export const BACK = 'חזרה';

/** Окно подтверждения с заголовком title (role dialog или alertdialog). */
export const confirmDialog = (page: Page, title: string): Locator =>
  page.getByRole('dialog', { name: title }).or(page.getByRole('alertdialog', { name: title }));

/** Окно открыто: текст, две кнопки, фокус по умолчанию на «חזרה» (комментарий программиста 12.11). */
export async function expectConfirmDialog(dialog: Locator, text: string, confirmLabel: string) {
  await expect(dialog).toBeVisible();
  await expect(dialog).toContainText(text);
  await expect(dialog.getByRole('button', { name: BACK, exact: true })).toBeVisible();
  await expect(dialog.getByRole('button', { name: confirmLabel, exact: true })).toBeVisible();
  await expect(dialog.getByRole('button', { name: BACK, exact: true })).toBeFocused();
}

/** Клик по затемнению вне окна (левый нижний угол — пустое место на всех трёх экранах). */
export async function clickOutside(page: Page) {
  const vp = page.viewportSize() ?? { width: 1440, height: 900 };
  await page.mouse.click(20, vp.height - 20);
}

/**
 * Запросы записи на сервер (POST/PUT/PATCH/DELETE), кроме чтения через rpc list_/get_ и обновления токена.
 * Во время «חזרה» / Escape / клика вне окна список должен оставаться пустым.
 */
export function trackWrites(page: Page): string[] {
  const writes: string[] = [];
  page.on('request', (req) => {
    const m = req.method();
    const url = req.url();
    if (!['POST', 'PUT', 'PATCH', 'DELETE'].includes(m)) return;
    if (/\/auth\/v1\//.test(url) || /\/rpc\/(list_|get_)/.test(url)) return;
    if (!/supabase\.co|\/api\//.test(url)) return;
    writes.push(`${m} ${url}`);
  });
  return writes;
}

/** Три способа отмены: «חזרה», Escape, клик вне окна. open() открывает окно заново и возвращает его. */
export async function dismissAllWays(page: Page, open: () => Promise<Locator>, afterEach: () => Promise<void>) {
  for (const way of ['back', 'escape', 'outside'] as const) {
    const dialog = await open();
    if (way === 'back') await dialog.getByRole('button', { name: BACK, exact: true }).click();
    if (way === 'escape') await page.keyboard.press('Escape');
    if (way === 'outside') await clickOutside(page);
    await expect(dialog, `окно закрыто (${way})`).toBeHidden();
    await afterEach();
  }
}
